<?php
session_start();require_once 'conexion.php';
if(empty($_SESSION['idUsuario'])){header('Location:index.php');exit;}
$msg='';$error='';$id=(int)$_SESSION['idUsuario'];
if($_SERVER['REQUEST_METHOD']==='POST'){$actual=$_POST['actual']??'';$nueva=$_POST['nueva']??'';$conf=$_POST['confirmar']??'';$st=$conn->prepare('SELECT passwordHash FROM usuario WHERE idUsuario=? AND estado=1');$st->bind_param('i',$id);$st->execute();$u=$st->get_result()->fetch_assoc();$st->close();if(!$u||!password_verify($actual,$u['passwordHash']))$error='La contraseña actual no es correcta.';elseif(strlen($nueva)<8)$error='La nueva contraseña debe tener al menos 8 caracteres.';elseif($nueva!==$conf)$error='Las contraseñas no coinciden.';else{$hash=password_hash($nueva,PASSWORD_DEFAULT);$st=$conn->prepare('UPDATE usuario SET passwordHash=? WHERE idUsuario=?');$st->bind_param('si',$hash,$id);$st->execute();$st->close();$msg='Contraseña actualizada correctamente.';}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cambiar contraseña - Kapykuá</title><link rel="stylesheet" href="style.css"></head><body class="account-page"><main class="account-panel"><h1>Seguridad de la cuenta</h1><p><?php echo htmlspecialchars($_SESSION['nombre']);?> · <?php echo htmlspecialchars($_SESSION['rol']);?></p><h2>Cambiar contraseña</h2><?php if($msg):?><p class="mensaje exito"><?php echo htmlspecialchars($msg);?></p><?php endif;?><?php if($error):?><p class="mensaje error"><?php echo htmlspecialchars($error);?></p><?php endif;?><form method="post"><label>Contraseña actual<input type="password" name="actual" required autocomplete="current-password"></label><label>Nueva contraseña<input type="password" name="nueva" minlength="8" required autocomplete="new-password"></label><label>Confirmar nueva contraseña<input type="password" name="confirmar" minlength="8" required autocomplete="new-password"></label><button>Actualizar contraseña</button></form><p class="admin-actions"><a href="index.php">← Volver a Kapykuá</a></p></main></body></html>
